<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { getDrawerContext } from './drawer-context.svelte.js'; export interface Props extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> { children?: Snippet; ref?: HTMLDivElement | null; } let { children, ref = $bindable(null), style, ...rest }: Props = $props(); const drawer = getDrawerContext(); let indentStyle = $derived(`--drawer-swipe-progress:${drawer.swipeProgress};${typeof style === 'string' ? style : ''}`);</script><div bind:this={ref} {...rest} style={indentStyle} data-drawer-open={drawer.open ? '' : undefined}>{@render children?.()}</div>
